// Builds a free stock-logo thumbnail URL, given a Kiwoom stock code (stk_cd).
//
// Uploaded company logos (STOCK_LOGOS) take priority - group-mark reuse
// across sibling tickers (e.g. Samsung Electronics / Samsung SDI share
// the same Samsung mark, LG energy/chem share the same LG mark). A few
// non-KRX names (Apple, Meta) are keyed by name since they have no
// ticker code. A code with no uploaded logo returns null, and the
// frontend falls back to an initial-letter avatar.

const STOCK_LOGOS = {
  '005930': 'data:image/png;base64,',
  '006400': 'data:image/png;base64,',
  '000660': 'data:image/png;base64,',
  '035720': 'data:image/png;base64,',
  '323410': 'data:image/png;base64,',
  '068270': 'data:image/png;base64,',
  '247540': 'data:image/png;base64,',
  '373220': 'data:image/png;base64,',
  '051910': 'data:image/png;base64,',
  '003670': 'data:image/png;base64,',
  '329180': 'data:image/png;base64,',
  '034020': 'data:image/png;base64,',
  '035420': 'data:image/png;base64,',
  '애플': 'data:image/png;base64,',
  '메타': 'data:image/png;base64,',
};

export function getThumbnailUrl(rawCode) {
  const code = String(rawCode || '').match(/\d{6}/)?.[0];
  if (!code) return null;
  return STOCK_LOGOS[code] || null;
}
